package mergesort

import "testing"

func equalSlices(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func TestMergeSortBasic(t *testing.T) {
	result := MergeSort([]int{3, 1, 4, 1, 5, 9, 2, 6})
	expected := []int{1, 1, 2, 3, 4, 5, 6, 9}
	if !equalSlices(result, expected) {
		t.Errorf("want %v, got %v", expected, result)
	}
}

func TestMergeSortEmpty(t *testing.T) {
	result := MergeSort([]int{})
	if len(result) != 0 {
		t.Errorf("want empty, got %v", result)
	}
}

func TestMergeSortSingle(t *testing.T) {
	result := MergeSort([]int{42})
	if !equalSlices(result, []int{42}) {
		t.Errorf("want [42], got %v", result)
	}
}

func TestMergeSortAlreadySorted(t *testing.T) {
	result := MergeSort([]int{1, 2, 3, 4, 5})
	if !equalSlices(result, []int{1, 2, 3, 4, 5}) {
		t.Errorf("want [1..5], got %v", result)
	}
}

func TestMergeSortReverse(t *testing.T) {
	result := MergeSort([]int{5, 4, 3, 2, 1})
	if !equalSlices(result, []int{1, 2, 3, 4, 5}) {
		t.Errorf("want [1..5], got %v", result)
	}
}

